test('취소 전에 관측한 take 거부는 같은 오류로 거부하며 한 번 닫는다', options, async () => {
  const error = new Error('take failed');
  const seen = [];
  const f = fixture((row, index) => seen.push([row, index]));
  const state = f.start();
  await waitFor(() => f.requests.length === 1);

